import { resolve } from '../claim-graph-resolver/src/resolver';
import { evaluatePolicy } from '../claim-graph-resolver/src/policy-evaluator';
import { detectCycles } from '../claim-graph-resolver/src/cycle-detector';
import policy from './cycle-detection-policy.json';
import graph from './recursive-attestation-chain.json';

const cycles = detectCycles(graph, { edgePredicates: ['attests','delegates-to'], maxDepth: 64 });
if (cycles.length > 0) {
  console.error('CYCLE:', cycles);
  process.exit(2);
}
const result = evaluatePolicy(graph, policy);
if (!result.ok) {
  console.error('POLICY:', result.code, result.message);
  process.exit(3);
}
const resolved = resolve(graph, { policy });
console.log(resolved);
